try:
    print('>>> x = 1j')
    print('>>> y = 3')
    print('>>> x <<= y')
    print('>>> x')
    x = 1j
    y = 3
    x <<= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
